package app.layan.test;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.*;import java.io.*;import app.layan.quran.*;
public final class BackgroundSupportRegression extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private String texts(View v){StringBuilder s=new StringBuilder();if(v instanceof TextView)s.append(((TextView)v).getText());if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)s.append(texts(((ViewGroup)v).getChildAt(i)));return s.toString();}
 public void onStart(){Bundle out=new Bundle();try{Activity a=startActivitySync(new Intent(getTargetContext(),DhikrBackgroundSettingsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final String[] text={""};runOnMainSync(()->text[0]=texts(a.getWindow().getDecorView()));boolean ar="ar".equals(a.getResources().getConfiguration().getLocales().get(0).getLanguage());for(String expected:ar?new String[]{"حالة التذكير","صوت الوسائط","تحسين البطارية","فتح إعدادات التطبيق","فتح تحسين البطارية"}:new String[]{"Reminder status","Media volume","Battery optimization","Open app settings","Open battery optimization"})if(!text[0].contains(expected))throw new AssertionError("Missing actual background settings control: "+expected);Bitmap image=NativeScreens.capture(this,a);File f=new File(a.getExternalFilesDir("tests"),"background-support-"+(ar?"ar":"en")+".png");f.getParentFile().mkdirs();try(FileOutputStream file=new FileOutputStream(f)){image.compress(Bitmap.CompressFormat.PNG,100,file);}runOnMainSync(a::finish);out.putString("result","PASS actual localized background status and settings controls; native screenshot");finish(Activity.RESULT_OK,out);}catch(Throwable e){out.putString("error",android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,out);}}
}
